**1. Correlating requests to responses over an async transport**

Responses can arrive out of send-order once a server processes calls concurrently. A real client tracks in-flight calls by `id`:

```python
import asyncio
import itertools
import json

class MCPClient:
    def __init__(self, send):
        self._send = send                      # write bytes to the transport
        self._next_id = itertools.count(1)
        self._pending = {}                     # id -> asyncio.Future

    async def call(self, method: str, params: dict) -> dict:
        req_id = next(self._next_id)
        fut = self._pending[req_id] = asyncio.get_running_loop().create_future()
        self._send(json.dumps({
            "jsonrpc": "2.0", "id": req_id, "method": method, "params": params
        }).encode())
        return await fut                        # resolved by on_message below

    def on_message(self, raw: bytes):
        msg = json.loads(raw)
        if "id" not in msg:
            return self._handle_notification(msg)     # e.g. notifications/progress
        fut = self._pending.pop(msg["id"], None)
        if fut and not fut.done():
            fut.set_result(msg.get("result", msg.get("error")))
```

The `_pending` dict is the whole trick: `id` is the only thing that lets the client match a late-arriving response to the call that triggered it, regardless of send order.

**2. Protocol error vs. tool-execution error (server side)**

```python
def handle_tools_call(req: dict) -> dict:
    try:
        name = req["params"]["name"]
    except KeyError:
        # malformed request -> JSON-RPC protocol error
        return {"jsonrpc": "2.0", "id": req.get("id"),
                "error": {"code": -32602, "message": "Invalid params: 'name' required"}}

    try:
        output = run_tool(name, req["params"].get("arguments", {}))
        return {"jsonrpc": "2.0", "id": req["id"],
                "result": {"content": [{"type": "text", "text": output}], "isError": False}}
    except ToolExecutionError as e:
        # the tool ran but failed -> still a JSON-RPC SUCCESS, isError flags it
        return {"jsonrpc": "2.0", "id": req["id"],
                "result": {"content": [{"type": "text", "text": str(e)}], "isError": True}}
```
